import { afterAll, beforeAll, describe, expect, test } from "vite-plus/test";
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { CssDocConfigFile } from "@cssdoc/config";
import type { CssDocEntry, CssModifier } from "@cssdoc/core";
import { emitCssApi } from "@cssdoc/typedoc";
import type { Token } from "@pantoken/tokens";
import { collectUnits, segmentMarkdown } from "./segment-markdown.ts";
import {
  annotateJsRequirement,
  assertNoUnknownReferences,
  componentSources,
  indexLocalVars,
  inferSyntax,
  makeImportSnippet,
  makeResolveSource,
  makeSourceResolver,
  pluginRecords,
  resolveSyntax,
  resolveToken,
  sourceMap,
  syntaxFromChain,
  writeCssIndexBlurb,
} from "./build-css-api.ts";

// A minimal IR token. Reference tokens carry syntax "*"; a concrete leaf carries a real syntax/value.
const tok = (name: string, extra: Partial<Token> = {}): Token => ({
  name,
  syntax: "*",
  inherits: true,
  value: "",
  ...extra,
});
const asEntry = (
  name: string,
  kind: CssDocEntry["kind"],
  modifiers: readonly Partial<CssModifier>[] = [],
): CssDocEntry => ({ name, kind, modifiers }) as CssDocEntry;

const repoRoot = join(import.meta.dirname, "..", "..");
let configuration: ReturnType<CssDocConfigFile["toConfiguration"]>;
let tmp: string;

beforeAll(() => {
  configuration = CssDocConfigFile.loadForFolder(repoRoot).toConfiguration();
  tmp = mkdtempSync(join(tmpdir(), "pantoken-cssapi-"));
});
afterAll(() => {
  rmSync(tmp, { recursive: true, force: true });
});

test("filters whole cssdoc examples before extracting page translations", () => {
  const css = join(tmp, "example-audiences.css");
  writeFileSync(
    css,
    [
      "/**",
      " * @component audience-test",
      " * @example labels=[automatica11y]",
      " * ### Audit caption",
      " * ```html",
      " * <button>Audit fixture</button>",
      " * ```",
      " * @example labels=[canvas-rce]",
      " * ```html",
      " * <button>Canvas only</button>",
      " * ```",
      " * @example labels=[canvas-rce,docs]",
      " * ```html",
      " * <button>Shared example</button>",
      " * ```",
      " * @example",
      " * ```html",
      " * <button>Unlabeled example</button>",
      " * ```",
      " */",
      ".pfx-audience-test { color: red; }",
    ].join("\n"),
  );
  const result = emitCssApi({
    css: [css],
    outputDirectory: tmp,
    configFile: CssDocConfigFile.loadForFolder(repoRoot),
  });
  const page = readFileSync(result.pages[0]!, "utf8");
  expect(page).not.toMatch(/Audit caption|Audit fixture|Canvas only|labels=\[/u);
  expect(collectUnits(segmentMarkdown(page)).map(({ text }) => text)).toEqual(
    expect.arrayContaining(["Shared example", "Unlabeled example"]),
  );
});

describe("inferSyntax", () => {
  test("url / data values", () => {
    expect(inferSyntax("url(#glyph)")).toBe("<url>");
    expect(inferSyntax("data:image/svg+xml,foo")).toBe("<url>");
  });
  test("colour values (hex, rgb, oklch, and light-dark pairs)", () => {
    expect(inferSyntax("#fff")).toBe("<color>");
    expect(inferSyntax("rgb(0, 0, 0)")).toBe("<color>");

