   if (!loaded) return;
   fn(loaded.config);
   saveConfig(configPath, loaded.config);
 }

 function stubAction(command: string): () => void {
   return () => {
     console.log(`"${command}" is not implemented yet — see .claude/plans/localization-engine.md.`);
     process.exit(1);
   };
 }

 /** Suffix explaining a lingering untranslated count for a "messages"-kind space's translate output. */
 function translateNote(provider: string | undefined): string {
   return aiProviderConfigured() || provider
     ? ""
     : " (no AI provider configured — pass --provider or set I18N_TRANSLATION_COMMAND)";
 }

 /** Reject a `--tier` that names no tier in `locales.tiers`, rather than silently translating none. */
 function assertKnownTier(config: I18nConfig, tier: string | undefined): void {
   if (tier === undefined || tier in config.locales.tiers) return;
   throw new CommanderError(
     1,
     "i18n.unknownTier",
     `Unknown tier "${tier}" — known: ${Object.keys(config.locales.tiers).join(", ")}`,
   );
 }

 /** Build the `i18n` commander program (exported for tests; `runI18nCli` is the process entry point). */
 export function createI18nCommand(options: { configPath?: string } = {}): Command {
   const program = new Command("i18n")
     .description("The pantoken localization engine CLI.")
     .exitOverride()
     .configureOutput({
       writeOut: (str) => process.stdout.write(str),
       writeErr: (str) => process.stderr.write(str),
     });

   program.option(
     "--config <path>",
     "path to i18n.config.json",
     options.configPath ?? "i18n.config.json",
   );

   const configDirOf = (): string => dirname(program.opts<{ config: string }>().config);

   /** Runs `messagesFn` for any space configured with `kind: "messages"`, `contentFn` for any
    *  `kind: "content"` space, or falls back to `command`'s stub message for anything else (e.g. an
    *  unconfigured or `"structural"` space with no handler). An omitted space defaults to
    *  `docs.guides`. */
   function withSpace(
     command: string,
     space: string | undefined,
     messagesFn: (config: I18nConfig, spaceId: string) => void | Promise<void>,
     contentFn: (config: I18nConfig, spaceId: string) => void | Promise<void>,
   ): void | Promise<void> {
     const configPath = program.opts<{ config: string }>().config;
     const loaded = loadConfigOrExit(configPath);
     if (!loaded) return;
     const spaceId = space ?? "docs.guides";
     if (loaded.config.spaces[spaceId]?.kind === "messages") {
       return messagesFn(loaded.config, spaceId);
     }
     if (loaded.config.spaces[spaceId]?.kind === "content") {
       return contentFn(loaded.config, spaceId);
     }
     stubAction(command)();
     return undefined;
   }

   program
     .command("extract")
     .addArgument(new Argument("[space]", "space id").argOptional())
     .action((space?: string) =>
       withSpace(
         "extract",
         space,
         (config, spaceId) => {
           const result = runExtractMessages(config, configDirOf(), spaceId);
           console.log(
             `Extracted ${String(result.unitCount)} unit(s) from ${spaceId} to ${result.potPath}.`,
           );
         },
         (config, spaceId) => {
           const result = runExtractContent(config, configDirOf(), spaceId);
           console.log(
             `Extracted ${String(result.unitCount)} unit(s) from ${spaceId} to ${result.potPath}.`,
           );
         },
       ),
     );

   program
     .command("translate")
     .addArgument(new Argument("[space]", "space id, e.g. docs.guides").argOptional())
     .option("--locale <locale>", "one locale")
     .option("--tier <tier>", "every locale in a tier")
     .option("--provider <provider>", "override the default provider profile")

