   const memory = TranslationMemory.load("hu", "test");
   const translateBatch = vi.fn((items: readonly { id: string; text: string }[]) =>
     Promise.resolve(
       Object.fromEntries(
         items.map((item) => [item.id, item.text === "Interfaces" ? item.text : `t:${item.text}`]),
