vi.mock("../.vitepress/i18n.ts", () => ({
  NON_ROOT_LOCALES: ["hu"],
  parseRequestedLocales: (requested: string | undefined, fallback: readonly string[]) =>
    requested ? requested.split(",") : fallback,
}));

