  this._mem = mem;
  this._poPath = poPath;
  this._poEntries = poEntries;
  this._poByKey = poEntries
    ? new Map(
        poEntries
          .filter((entry) => !entry.msgid.includes("{{ptk_code_") || !entry.obsolete)
          .map((entry) => [`${entry.msgctxt ?? ""}\0${entry.msgid}`, entry]),
      )
    : undefined;
}

/** Load (or start) the memory for a docs namespace. The API namespace uses a PO catalog. */
static load(locale: string, namespace: string): TranslationMemory {
  if (namespace === "api") {
    const poPath = join(import.meta.dirname, "..", "..", "l10n", locale, "docs.api.po");
    return new TranslationMemory(undefined, poPath, parsePo(readCatalog(poPath) ?? ""));
  }
  const path = join(cacheDir, `${locale}.${namespace}.json`);
  return new TranslationMemory(
    SharedTranslationMemory.open(path, { prune: namespace !== "api" }),
  );
}

get(kind: string, source: string): string | undefined {
  // DOCS_TRANSLATION_FORCE turns every lookup into a miss, so `:force` really does retranslate.
  if (process.env.DOCS_TRANSLATION_FORCE === "1") return undefined;
  if (this._poByKey) {
    const entry = this._poByKey.get(`docs.api:${kind}\0${source}`);
    const translation =
      entry && (!source.includes("{{ptk_code_") || (!entry.fuzzy && !entry.obsolete))
        ? entry.msgstr
        : undefined;
    if (translation !== undefined && translation !== "")
      assertGeneratedTranslation(source, translation);
    if (translation) this._poHits++;
    return translation || undefined;
  }
  const translation = this._mem!.get(keyFor(kind, source));
  if (translation !== undefined) assertGeneratedTranslation(source, translation);
  return translation;
}

set(kind: string, source: string, translation: string, options?: { verbatim?: boolean }): void {
  assertGeneratedTranslation(source, translation);
  const verbatim = options?.verbatim === true;
  if (this._poByKey) {
    this.setPoTranslation(kind, source, translation, verbatim);
  } else {
    this._mem!.set(keyFor(kind, source), translation);
    if (verbatim) this._mem!.set(verbatimKey(kind, source), "1");
  }
  this.misses++;
}

private setPoTranslation(
  kind: string,
  source: string,
  translation: string,
  verbatim: boolean,
): void {
  const key = `docs.api:${kind}\0${source}`;
  let entry = this._poByKey!.get(key);
  if (!entry) {
    entry = {
      msgid: source,
      msgstr: "",
      msgctxt: `docs.api:${kind}`,
      references: [],
      flags: [],
      fuzzy: false,
      obsolete: false,
    };
    this._poEntries!.push(entry);
    this._poByKey!.set(key, entry);
  }

