import { readFileSync } from 'node:fs';
import { parsePo } from '@pantoken/i18n-engine';
import { TranslationMemory, translateUnits, keyFor } from './docs/scripts/translation-memory.ts';
import { isWcagReference } from './docs/scripts/api-verbatim.ts';
const entries = parsePo(readFileSync('l10n/ar/docs.api.po', 'utf8'));
const wcag = entries.find(e => !e.obsolete && isWcagReference(e.msgid) && e.msgid.includes('1.4.3'));
const scoped = entries.find(e => !e.obsolete && e.msgid.startsWith('<!-- pantoken-value-scope:') && e.msgid.includes('{{ptk_code_') && e.msgid === e.msgstr);
if (!wcag || !scoped) throw new Error('Expected Arabic catalog fixtures not found');
let calls = 0;
const adapter = { name: 'offline', translateMarkdown: async text => text, translateText: async text => { calls++; if (text.startsWith('<!--')) throw new Error('Scope leaked'); return 'مترجم ' + text; } };
const memory = TranslationMemory.load('ar', 'api');
const units = [{kind: 'prose', source: wcag.msgid}, {kind: 'prose', source: scoped.msgid}];
const options = {locale: 'ar', requiredVerbatimSources: new Set([wcag.msgid])};
const first = await translateUnits(adapter, memory, units, options);
const second = await translateUnits(adapter, memory, units, options);
if (calls !== 1 || first.get(keyFor('prose', wcag.msgid)) !== wcag.msgid || first.get(keyFor('prose', scoped.msgid)) !== second.get(keyFor('prose', scoped.msgid))) throw new Error('Offline cache verification failed');
console.log('Offline Arabic catalog: WCAG copied; scoped prose translated once and reused; no catalogs written.');
