import {readFileSync,readdirSync} from 'node:fs';import {parsePo} from './tools/i18n-engine/dist/index.mjs';import {GLOSSARY_TERMS} from './docs/scripts/glossary.ts'; const terms=new Set(GLOSSARY_TERMS.map(t=>t.term));let totals={active:0,obsolete:0,fuzzy:0,missing:0};for(const l of readdirSync('l10n')){let es;try{es=parsePo(readFileSync(`l10n/${l}/docs.api.po`,'utf8'));}catch{continue;}const ts=es.filter(e=>e.msgctxt==='docs.api:text'&&terms.has(e.msgid));for(const e of ts){totals[e.obsolete?'obsolete':'active']++;if(e.fuzzy)totals.fuzzy++;}totals.missing+=terms.size-new Set(ts.map(e=>e.msgid)).size;}console.log(JSON.stringify({terms:terms.size,totals}));
NODE

