+  existsSync.mockReturnValue(true);
+  readFileSync.mockReturnValue(
+    '#~ msgctxt "docs.api:text"\n#~ msgid "Usage"\n#~ msgstr "Használat"\n\n' +
+      '#, fuzzy\n#~ msgctxt "docs.api:text"\n#~ msgid "Value"\n#~ msgstr "Érték"\n\n' +
